import{_ as t,o as n,c as r,a2 as i}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"HTML-Blöcke","description":"Eigenes HTML auf einer Seite einbinden — mit und ohne Formularfelder.","frontmatter":{"title":"HTML-Blöcke","description":"Eigenes HTML auf einer Seite einbinden — mit und ohne Formularfelder."},"headers":[],"relativePath":"seiten/html-bloecke.md","filePath":"seiten/html-bloecke.md","lastUpdated":1786434193000}'),a={name:"seiten/html-bloecke.md"};function l(o,e,d,s,h,c){return n(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="html-blocke" tabindex="-1">HTML-Blöcke <a class="header-anchor" href="#html-blocke" aria-label="Permalink to &quot;HTML-Blöcke&quot;">​</a></h1><p>Zwei Blöcke erlauben eigenen HTML-Code, wenn die vorhandenen Blöcke nicht ausreichen.</p><table tabindex="0"><thead><tr><th>Block</th><th>Zweck</th></tr></thead><tbody><tr><td><strong>HTML</strong></td><td><em>Eigenes HTML einbinden oder per KI erstellen</em></td></tr><tr><td><strong>HTML mit Formularfeldern</strong></td><td><em>Eigenes HTML einbinden und Formularfelder per KI hinzufügen</em></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Erst prüfen, ob es ohne geht</p><p>HTML-Blöcke sind mächtig, aber aufwendiger zu pflegen als die vorgefertigten Blöcke: Sie werden von Umgestaltungen nicht mitgezogen und sind für Kollegen ohne HTML-Kenntnisse nicht änderbar.</p><p>Prüfen Sie zuerst, ob <a href="/seiten/layout-bloecke">Layout-Blöcke</a> mit Hintergrundfarbe und Border radius reichen.</p></div><hr><h2 id="html" tabindex="-1">HTML <a class="header-anchor" href="#html" aria-label="Permalink to &quot;HTML&quot;">​</a></h2><h3 id="bearbeiten" tabindex="-1">Bearbeiten <a class="header-anchor" href="#bearbeiten" aria-label="Permalink to &quot;Bearbeiten&quot;">​</a></h3><p>Über <strong>HTML bearbeiten</strong> öffnet sich der Code-Editor mit <strong>HTML Code</strong> und <strong>Live Vorschau</strong> nebeneinander.</p><table tabindex="0"><thead><tr><th>Funktion</th><th>Wirkung</th></tr></thead><tbody><tr><td><strong>Mit KI generieren</strong></td><td>Beschreiben statt schreiben</td></tr><tr><td><strong>Vorherige HTML-Version wiederherstellen</strong></td><td>Nimmt die letzte Erzeugung zurück</td></tr><tr><td><strong>Höhe automatisch anpassen</strong></td><td>Höhe folgt dem Inhalt</td></tr></tbody></table><p>Bei fehlerhaftem Code erscheint <em>Vorschau-Fehler</em>, bei fehlgeschlagener Erzeugung <em>HTML konnte nicht generiert werden</em>.</p><h3 id="mit-ki-arbeiten" tabindex="-1">Mit KI arbeiten <a class="header-anchor" href="#mit-ki-arbeiten" aria-label="Permalink to &quot;Mit KI arbeiten&quot;">​</a></h3><p>Das Eingabefeld erwartet eine Beschreibung der gewünschten Änderung — etwa „Füge eine Fußzeile hinzu&quot; oder „Mache die Karte responsiv&quot;.</p><div class="tip custom-block"><p class="custom-block-title">Schrittweise vorgehen</p><p>Die KI ändert den vorhandenen Code. Kleine, klar formulierte Änderungen führen zu besseren Ergebnissen als eine lange Wunschliste.</p><p><em>Vorherige HTML-Version wiederherstellen</em> nimmt genau einen Schritt zurück — bei wichtigen Zwischenständen kopieren Sie den Code besser heraus.</p></div><h3 id="vorlagenvariablen" tabindex="-1">Vorlagenvariablen <a class="header-anchor" href="#vorlagenvariablen" aria-label="Permalink to &quot;Vorlagenvariablen&quot;">​</a></h3><p>Der Editor weist darauf hin: <em>Verwenden Sie {{ }} für Vorlagenvariablen. Beispiel: {{variableName}}</em></p><p>Damit setzen Sie Werte aus dem Zusammenhang in den HTML-Code ein.</p><hr><h2 id="html-mit-formularfeldern" tabindex="-1">HTML mit Formularfeldern <a class="header-anchor" href="#html-mit-formularfeldern" aria-label="Permalink to &quot;HTML mit Formularfeldern&quot;">​</a></h2><p>Wie der HTML-Block, aber die enthaltenen Eingabefelder geben Daten zurück.</p><div class="danger custom-block"><p class="custom-block-title">Felder brauchen ein name- oder id-Attribut</p><p>Der Editor warnt ausdrücklich:</p><blockquote><p><em>Eingabefelder ohne name oder id werden nicht in die Flow-Payload aufgenommen. Fügen Sie jedem Eingabefeld, das übermittelt werden soll, ein name- oder id-Attribut hinzu.</em></p></blockquote><p>Ohne eines der beiden Attribute geht der eingegebene Wert <strong>stillschweigend verloren</strong> — es gibt keine Fehlermeldung.</p></div><h3 id="ubergabe-prufen" tabindex="-1">Übergabe prüfen <a class="header-anchor" href="#ubergabe-prufen" aria-label="Permalink to &quot;Übergabe prüfen&quot;">​</a></h3><p>Über <strong>Flow-Formular-Payload Vorschau</strong> und <strong>Vorschau aktualisieren</strong> sehen Sie, welche Werte tatsächlich übergeben würden.</p><div class="tip custom-block"><p class="custom-block-title">Vor dem Produktivgang immer prüfen</p><p>Diese Vorschau ist die einzige verlässliche Kontrolle, ob Ihre Felder ankommen. Fehlt eines darin, fehlt das <code>name</code>- oder <code>id</code>-Attribut.</p></div><hr><h2 id="grenzen-und-vorsicht" tabindex="-1">Grenzen und Vorsicht <a class="header-anchor" href="#grenzen-und-vorsicht" aria-label="Permalink to &quot;Grenzen und Vorsicht&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Was Sie beachten sollten</p><ul><li><strong>Keine bedingte Anzeige innerhalb des HTML.</strong> Die <a href="/seiten/sichtbarkeit">bedingte Sichtbarkeit</a> wirkt auf den Block als Ganzes, nicht auf Teile darin.</li><li><strong>Keine Validierung.</strong> Pflichtfeld-Prüfungen der normalen Eingabeblöcke greifen hier nicht.</li><li><strong>Gestaltung ist Ihre Sache.</strong> Der Block übernimmt nicht automatisch das Erscheinungsbild der Seite.</li><li><strong>Auf schmalen Bildschirmen prüfen.</strong> Feste Breiten brechen dort.</li></ul></div><div class="danger custom-block"><p class="custom-block-title">Keine vertraulichen Daten im Code</p><p>Der HTML-Code wird an Besucher ausgeliefert und ist im Browser einsehbar. Legen Sie dort keine Zugangsdaten, Schlüssel oder internen Adressen ab.</p></div><hr><h2 id="wann-welcher-block" tabindex="-1">Wann welcher Block <a class="header-anchor" href="#wann-welcher-block" aria-label="Permalink to &quot;Wann welcher Block&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Ziel</th><th>Block</th></tr></thead><tbody><tr><td>Gestalteter Text, Karten, Abstände</td><td><a href="/seiten/layout-bloecke">Layout-Blöcke</a></td></tr><tr><td>Externe Inhalte einbinden</td><td><strong>Einbinden</strong> (iframe)</td></tr><tr><td>Eigene Optik ohne Eingabe</td><td><strong>HTML</strong></td></tr><tr><td>Eigene Optik mit Eingabefeldern</td><td><strong>HTML mit Formularfeldern</strong></td></tr><tr><td>Normale Datenerfassung</td><td><a href="/seiten/eingabebloecke">Eingabeblöcke</a></td></tr></tbody></table><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/seiten/bloecke">Blockübersicht</a></li><li><a href="/seiten/eingabebloecke">Eingabeblöcke</a></li><li><a href="/seiten/sichtbarkeit">Bedingte Sichtbarkeit</a></li></ul>',32)])])}const g=t(a,[["render",l]]);export{u as __pageData,g as default};
